#include <windows.h>
#include <stdio.h>
#include <stdint.h>
int main(void){ STARTUPINFOA si={.cb=sizeof(si)}; PROCESS_INFORMATION pi={0}; char cmd[]="work/native-probe/pokeemerald-bench.exe --script work/upstream-emerald/tools/wasm_replays/mudkip_starter.txt --golden work/upstream-emerald/tools/native/bench_golden.json --passes 1"; if(!CreateProcessA(NULL,cmd,NULL,NULL,FALSE,DEBUG_ONLY_THIS_PROCESS,NULL,NULL,&si,&pi))return 2; DEBUG_EVENT ev={0}; uintptr_t base=0; while(WaitForDebugEvent(&ev,12000)){DWORD action=DBG_CONTINUE; if(ev.dwDebugEventCode==CREATE_PROCESS_DEBUG_EVENT)base=(uintptr_t)ev.u.CreateProcessInfo.lpBaseOfImage; if(ev.dwDebugEventCode==EXCEPTION_DEBUG_EVENT){ EXCEPTION_RECORD *e=&ev.u.Exception.ExceptionRecord; if(e->ExceptionCode==EXCEPTION_ACCESS_VIOLATION){CONTEXT c={.ContextFlags=CONTEXT_FULL};HANDLE t=OpenThread(THREAD_ALL_ACCESS,FALSE,ev.dwThreadId);GetThreadContext(t,&c);printf("base=%llx rip=%llx exc-at=%llx rax=%llx rcx=%llx rdx=%llx r8=%llx rsp=%llx\n",base,c.Rip-base+0x140000000,e->ExceptionInformation[1],c.Rax,c.Rcx,c.Rdx,c.R8,c.Rsp);uintptr_t stack[200]; SIZE_T got=0;ReadProcessMemory(pi.hProcess,(void*)c.Rsp,stack,sizeof(stack),&got); for(int i=0;i<got/8;i++)if(stack[i]>=base && stack[i]<base+0x900000)printf("%d %llx\n",i,stack[i]-base+0x140000000); TerminateProcess(pi.hProcess,1);return 0;}if(e->ExceptionCode!=EXCEPTION_BREAKPOINT)action=DBG_EXCEPTION_NOT_HANDLED;} if(ev.dwDebugEventCode==EXIT_PROCESS_DEBUG_EVENT)break;ContinueDebugEvent(ev.dwProcessId,ev.dwThreadId,action);} return 3;}
